  // 0x49c6a0
  async unlock() {
    const d = this.rt.data;
    if (!d.takeUnlock()) return;
    this.setCurrentChar(d.static.quickRace.lockedCharIx);
    this.rt.sound.playVoice("unlock");
    await this.rt.showModal(TfrmUnlock);
  }
