var FONT_ARIAL = "Arial, Helvetica, sans-serif";
function wrappedHeight(g, label) {
  const f = label.font;
  g.font = `${f.bold ? "bold " : ""}${f.size}px ${f.name}`;
  return wrapLines(g, label.text, label.w).length * Math.round(f.size * 1.2);
}
