  const ch = Math.max(1, Math.round(window.innerHeight * dpr));
  let h = ch;
  if (ch > cw * 1.15) h = useTouch(settings) ? Math.min(Math.round(ch * 0.62), Math.round(cw * 1.2)) : Math.min(ch, Math.round(cw * 1.5));
  const mode = softwareMode(resolution);
