    w.writeInteger("OPTIONS", "NRLAPS", track.nrLaps);
    w.writeBool("OPTIONS", "OPPONENTS", !track.isChase);
    w.writeBool("ETAPPE", "BRITISH", track.british);
    w.writeInteger("LEAGUE", "LEAGUE", s.difficulty);
    w.writeInteger("PLAYER", "DAMAGE", 0);
