    w.writeInteger("PLAYER", "TURBO_AMOUNT", 100);
    w.writeBool("PLAYER", "MOTOR", true);
    w.writeBool("PLAYER", "BANDEN", true);
    w.writeBool("PLAYER", "ABS", true);
    w.writeBool("PLAYER", "VERSNELLINGSBAK", true);
    w.writeInteger("PLAYER", "POSITION", 4);
