    w.writeBool("PLAYER", "BANDEN", r.hasTuneUp(1));
    w.writeBool("PLAYER", "ABS", r.hasTuneUp(2));
    w.writeBool("PLAYER", "VERSNELLINGSBAK", r.hasTuneUp(3));
